import assert from "node:assert/strict";
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

const [before, candidate, output] = process.argv.slice(2);
assert(before && candidate && output);
const observations = [];
for (const source of [before, candidate]) {
  const load = (file) => import(pathToFileURL(resolve(source, "src/project-run/task-scheduler", file)).href);
  const { runTaskGraph } = await load("scheduler.ts");
  const { prepareTaskGraph } = await load("graph.ts");
  const { decideScheduler } = await load("scheduler-decision.ts");
  const controller = new AbortController();
  const events = [];
  const executed = [];
  const graph = { tasks: [{ id: "first" }, { id: "z-last-lexical" }, { id: "a-first-lexical" }, { id: "middle" }] };
  const result = await runTaskGraph({
    graph,
    maxParallel: 1,
    signal: controller.signal,
    diagnosticLogger: { close: () => "disabled", observe: (event) => events.push(event) },
    execute: (task) => { executed.push(task.id); controller.abort(); return task.id; }
  });
  const decisions = events.filter((event) => event.event === "scheduler.decision").map((event) => event.details);
  const cancellation = decisions.find((decision) => decision.kind === "cancel-pending");
  assert.deepEqual(executed, ["first"]);
  assert.deepEqual(cancellation.taskIds, ["z-last-lexical", "a-first-lexical", "middle"]);
  assert(Object.isFrozen(cancellation.taskIds));
  assert.equal(result.cancelled, true);
  assert.deepEqual(result.settlements.map(({ task, settlement }) => [task.id, settlement.kind]), [
    ["first", "completed"], ["z-last-lexical", "cancelled-before-start"], ["a-first-lexical", "cancelled-before-start"], ["middle", "cancelled-before-start"]
  ]);
  const suppliedOrder = ["middle", "a-first-lexical", "z-last-lexical"];
  const pureDecision = decideScheduler(Object.freeze({
    graph: prepareTaskGraph(graph, 1), maxParallel: 1,
    activeScopeIds: Object.freeze([]), isAbortRequested: true, isCancelled: false,
    pendingTaskIds: Object.freeze(suppliedOrder), runningMutexes: Object.freeze([]),
    runningTaskIds: Object.freeze(["first"]), settledTasks: Object.freeze([])
  }), Object.freeze({ kind: "execution-started" }));
  assert.equal(pureDecision.kind, "cancel-pending");
  assert.deepEqual(pureDecision.taskIds, suppliedOrder);
  assert(Object.isFrozen(pureDecision.taskIds));
  observations.push({ source, executed, decisions, result, pureDecision });
}
const [left, right] = observations;
assert.deepEqual({ ...left, source: null }, { ...right, source: null });
writeFileSync(output, JSON.stringify({ runtime: process.version, method: "direct shell cancellation and standalone snapshot-order equivalence; no timing", observations }, null, 2), { flag: "wx" });
console.log("Cancellation ordered decisions, drain, settlements, and standalone supplied order match exactly.");

import assert from "node:assert/strict";
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

const [source, output] = process.argv.slice(2);
assert(source && output);
const { defineConfig, run } = await import(pathToFileURL(resolve(source, "src/index.ts")).href);
const originalFreeze = Object.freeze;
const samples = [];
for (const size of [8, 16, 32]) {
  const counts = { shellSnapshots: 0, snapshotPendingIds: 0, snapshotSettledEntries: 0, candidateObjectFreezes: 0 };
  const definition = defineConfig({
    checks: Array.from({ length: size }, (_, i) => ({ checkId: `task-${i}`, displayName: `task-${i}`, execute: () => ({ status: "passed", data: {} }) })),
    scheduler: { maxParallel: 4 },
    outputs: { diagnosticLogging: { enabled: false }, machinePublication: { enabled: false }, progressRendering: { enabled: false } }
  });
  Object.freeze = function countedFreeze(value) {
    if (value && typeof value === "object" && "pendingTaskIds" in value && "settledTasks" in value && "graph" in value) {
      counts.shellSnapshots++;
      counts.snapshotPendingIds += value.pendingTaskIds.length;
      counts.snapshotSettledEntries += value.settledTasks.length;
    }
    if (value && typeof value === "object" && "canAdmit" in value && "task" in value) counts.candidateObjectFreezes++;
    return originalFreeze(value);
  };
  try {
    const result = await run(definition, { projectRoot: "/workspace/vibe-check" });
    assert.equal(result.kind, "completed");
    assert.equal(result.aggregate, "passed");
    assert.equal(result.snapshot.checks.length, size);
    samples.push({ size, parallel: 4, ...counts });
  } finally {
    Object.freeze = originalFreeze;
  }
}
writeFileSync(output, JSON.stringify({ source, method: "complete public sourceAPI Run; temporary transparent freeze wrapper; counts only, no timing claims", runtime: process.version, samples }, null, 2), { flag: "wx" });
console.log(JSON.stringify(samples));

import { createHash } from "node:crypto";
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import assert from "node:assert/strict";

const [source, shape, sizeText, parallelText, output, warmupsText = "3", samplesText = "9"] = process.argv.slice(2);
const size = Number(sizeText);
const parallel = Number(parallelText);
const warmups = Number(warmupsText);
const samples = Number(samplesText);
assert([size, parallel, warmups, samples].every((n) => Number.isSafeInteger(n) && n > 0));
assert(shape === "independent" || shape === "chain");
assert(source && output);
const sourceRoot = resolve(source);
const sha256 = (text) => createHash("sha256").update(text).digest("hex");
function manifest(directory, prefix = "") {
  return readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name < b.name ? -1 : a.name > b.name ? 1 : 0).flatMap((entry) => {
    const relative = prefix + entry.name;
    const path = resolve(directory, entry.name);
    assert(!entry.isSymbolicLink());
    return entry.isDirectory() ? manifest(path, relative + "/") : [{ path: relative, sha256: sha256(readFileSync(path)) }];
  });
}
const beforeIdentity = sha256(JSON.stringify(manifest(resolve(sourceRoot, "src"))));
const { defineConfig, run } = await import(pathToFileURL(resolve(sourceRoot, "src/index.ts")).href);
const ids = Array.from({ length: size }, (_, i) => `task-${String(i).padStart(6, "0")}`);
const definition = defineConfig({
  checks: ids.map((checkId, i) => ({
    checkId,
    displayName: checkId,
    execute: () => ({ status: "passed", data: {} }),
    ...(shape === "chain" && i > 0 ? { dependsOn: [ids[i - 1]] } : {})
  })),
  scheduler: { maxParallel: parallel, admissionPolicy: { kind: "static" } },
  outputs: {
    diagnosticLogging: { enabled: false },
    machinePublication: { enabled: false },
    progressRendering: { enabled: false }
  }
});
let signature;
let snapshotDigest;
let declarativeFingerprint;
function verify(result) {
  assert.equal(result.kind, "completed");
  assert.equal(result.aggregate, "passed");
  assert.equal(result.snapshot.checks.length, size);
  assert.equal(result.snapshot.records.length, 0);
  assert.deepEqual(result.snapshot.checks.map((check) => check.checkId), ids);
  assert(result.snapshot.checks.every((check) => check.outcome.status === "passed"));
  assert.deepEqual(result.checkMessages, []);
  assert.deepEqual(result.definitionWarnings, []);
  for (const output of Object.values(result.outputs)) {
    assert.equal(output.enabled, false);
    assert.equal(output.status, "disabled");
  }
  for (const channel of Object.values(result.outputs.diagnosticLogging.channels)) {
    assert.equal(channel.enabled, false);
    assert.equal(channel.status, "disabled");
    assert.equal(channel.file, null);
  }
  assert.deepEqual(result.checkDurations.map((duration) => duration.checkId), ids);
  assert(result.checkDurations.every((duration) => typeof duration.durationMs === "number" && Number.isFinite(duration.durationMs) && duration.durationMs >= 0));
  const digest = sha256(JSON.stringify(result.snapshot));
  const current = sha256(JSON.stringify({ ...result, checkDurations: result.checkDurations.map(({checkId}) => ({ checkId, durationMs: "finite-nonnegative" })) }));
  if (signature !== undefined) {
    assert.equal(current, signature);
    assert.equal(digest, snapshotDigest);
    assert.equal(result.declarativeFingerprint, declarativeFingerprint);
  }
  signature = current;
  snapshotDigest = digest;
  declarativeFingerprint = result.declarativeFingerprint;
}
const observations = [];
for (let index = 0; index < warmups + samples; index++) {
  const start = performance.now();
  const result = await run(definition, { projectRoot: "/workspace/vibe-check" });
  const wallMs = performance.now() - start;
  verify(result);
  observations.push({ index, warmup: index < warmups, wallMs });
}
assert.equal(sha256(JSON.stringify(manifest(resolve(sourceRoot, "src")))), beforeIdentity);
const evidence = {
  sourceRoot, sourceManifestSha256: beforeIdentity, scriptSha256: sha256(readFileSync(import.meta.filename)),
  shape, size, parallel, warmups, samples,
  runtime: { version: process.version, versions: process.versions, execPath: process.execPath },
  scope: "complete public sourceAPI run; import/Definition/verification/IO excluded; not installed package or Gate",
  signature, snapshotDigest, declarativeFingerprint, observations,
  processMemory: process.memoryUsage(), processResourceUsage: process.resourceUsage()
};
writeFileSync(output, JSON.stringify(evidence, null, 2), { flag: "wx" });
console.log(JSON.stringify({ shape, size, parallel, sourceRoot, signature, output }));

import assert from "node:assert/strict";
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const root = import.meta.dirname;
const directory = resolve(root, "raw/formal");
const median = (values) => {
  const sorted = [...values].sort((a, b) => a - b);
  assert(sorted.length > 0);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
};
const distribution = (values) => ({ median: median(values), mad: median(values.map((value) => Math.abs(value - median(values)))), min: Math.min(...values), max: Math.max(...values) });
const groups = new Map();
for (const file of readdirSync(directory).filter((file) => file.endsWith(".json")).sort()) {
  const raw = JSON.parse(readFileSync(resolve(directory, file), "utf8"));
  assert.equal(raw.samples, 9);
  assert.equal(raw.warmups, 3);
  assert.equal(raw.observations.length, 12);
  const samples = raw.observations.filter((sample) => !sample.warmup).map((sample) => sample.wallMs);
  assert.equal(samples.length, 9);
  assert(samples.every((sample) => Number.isFinite(sample) && sample >= 0));
  const runtime = file.startsWith("node-") ? "node" : "bun";
  assert.equal(raw.runtime.version, runtime === "node" ? "v24.18.0" : "v24.3.0");
  if (runtime === "bun") assert.equal(raw.runtime.versions.bun, "1.3.14");
  const key = `${runtime}-${raw.shape}-${raw.size}-p${raw.parallel}`;
  const group = groups.get(key) ?? [];
  group.push({ file, sourceManifestSha256: raw.sourceManifestSha256, scriptSha256: raw.scriptSha256, signature: raw.signature, snapshotDigest: raw.snapshotDigest, declarativeFingerprint: raw.declarativeFingerprint, side: raw.sourceRoot.endsWith("/before") ? "before" : "candidate", ...distribution(samples), samples });
  groups.set(key, group);
}
const workloads = [];
for (const [key, processes] of groups) {
  assert.equal(processes.length, 4);
  assert.deepEqual(processes.map((process) => process.side), ["before", "candidate", "candidate", "before"]);
  for (const field of ["scriptSha256", "signature", "snapshotDigest", "declarativeFingerprint"]) assert.equal(new Set(processes.map((process) => process[field])).size, 1);
  for (const side of ["before", "candidate"]) assert.equal(new Set(processes.filter((process) => process.side === side).map((process) => process.sourceManifestSha256)).size, 1);
  const before = distribution(processes.filter((process) => process.side === "before").flatMap((process) => process.samples));
  const candidate = distribution(processes.filter((process) => process.side === "candidate").flatMap((process) => process.samples));
  const pairChangesPct = [(processes[1].median / processes[0].median - 1) * 100, (processes[2].median / processes[3].median - 1) * 100];
  workloads.push({ key, before, candidate, medianChangePct: (candidate.median / before.median - 1) * 100, pairChangesPct, processes });
}
assert.equal(workloads.length, 14);
writeFileSync(resolve(root, "summary.json"), JSON.stringify({ scope: "supported Node public sourceAPI primary; Bun independently reported; no installed package/Gate claim; pooled 18 samples not independent host experiments", processCount: 56, workloads }, null, 2), { flag: "wx" });
for (const workload of workloads) console.log(`${workload.key}: ${workload.before.median.toFixed(3)} -> ${workload.candidate.median.toFixed(3)} ms (${workload.medianChangePct.toFixed(1)}%), paired ${workload.pairChangesPct.map((change) => change.toFixed(1)).join("/")}%`);
